-- WAR.INC.RISE(AU)[32+64]-V15.01
-- Do not edit this file. Any change breaks the decoder.
local _rqblnx = 146
local _hozxur = 34
local _urnyly = 43
local _usmped = ""

local _dpjaiz = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"

local function _axgfdt(a, b)
	local r, p = 0, 1
	for _ = 1, 8 do
		local x, y = a % 2, b % 2
		if x ~= y then r = r + p end
		a = (a - x) / 2; b = (b - y) / 2; p = p * 2
	end
	return r
end

local function _ftnmfa(d)
	d = d:gsub("[^" .. _dpjaiz .. "=]", "")
	local o = {}
	local bits = (d:gsub("[%w%+/=]", function(c)
		if c == "=" then return "" end
		local f, s = (_dpjaiz:find(c, 1, true) - 1), ""
		for i = 6, 1, -1 do
			s = s .. (f % 2 ^ i - f % 2 ^ (i - 1) > 0 and "1" or "0")
		end
		return s
	end))
	local n = 0
	for i = 1, #bits - 7, 8 do
		local c = 0
		for j = 0, 7 do
			if bits:sub(i + j, i + j) == "1" then c = c + 2 ^ (7 - j) end
		end
		n = n + 1
		o[n] = string.char(c)
	end
	return table.concat(o)
end

local _ucesuv = _ftnmfa(_usmped)
local _qppqxi = { _rqblnx, _hozxur, _urnyly }
local _favdqe = {}
for i = 1, #_ucesuv do
	_favdqe[i] = string.char(_axgfdt(_ucesuv:byte(i), _qppqxi[(i - 1) % 3 + 1]))
end

local _hhmlsh = load or loadstring
local _cidnon, _ihzthn = _hhmlsh(table.concat(_favdqe), "=w")
if not _cidnon then
	gg.alert("Corrupted file: " .. tostring(_ihzthn))
	os.exit()
end
_cidnon()
